const $=s=>document.querySelector(s);let connected=false,connecting=false,route=false,step=0,playing=false,track=0,elapsed=0,voice=true;let toastTimer,ctx,gain,nodes=[];const tracks=[['Open Sky','轻盈 / 合成氛围音',220],['Blue Hour','舒缓 / 合成氛围音',174.61],['Above the City','流动 / 合成氛围音',261.63]];const routes={city:[8.2,16,'城市观景平台'],campus:[12.6,24,'大学城'],river:[5.4,11,'江畔公园']};
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2400)}
function show(s){document.querySelectorAll('.screen').forEach(e=>e.hidden=e.id!==s);document.querySelectorAll('.bottom-nav button').forEach(b=>{b.classList.toggle('active',b.dataset.go===s);b.setAttribute('aria-current',b.dataset.go===s?'page':'false')});window.scrollTo({top:0,behavior:'instant'})}document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>show(b.dataset.go));
function sync(){ $('#status').textContent=connected?'设备已连接':'设备待连接';$('#connection-info').textContent=connected?'眼镜与耳机已同步 · 演示模式':'体验眼镜与耳机协同工作';$('#battery').textContent=connected?'模拟电量 88%':'—';$('#connection-dot').classList.toggle('connected',connected);$('#connect').textContent=connected?'✓':'↗';$('#connect').setAttribute('aria-label',connected?'设备已连接':'连接演示设备');$('#settings-status').textContent=connected?'眼镜与耳机已同步':'未连接';$('#disconnect').textContent=connected?'断开':'连接'}
function connect(){if(connected){toast('眼镜与耳机已连接');return}if(connecting)return;connecting=true;$('#status').textContent='正在连接…';$('#connect').disabled=true;setTimeout(()=>{connected=true;connecting=false;$('#connect').disabled=false;sync();toast('连接成功，可以开始旅程')},800)}$('#connect').onclick=connect;$('#disconnect').onclick=()=>{if(!connected){connect();return}connected=false;route=false;step=0;stopSound();sync();renderRoute();toast('设备已断开')};
function renderRoute(){const [km,min,name]=routes[$('#destination').value];const frac=step/4;$('#distance').textContent=(km*(1-frac)).toFixed(1);$('#duration').textContent=Math.round(min*(1-frac));$('#hud-time').textContent=`${Math.round(min*(1-frac))} min`;const turns=['沿当前路线前行','前方 200 m 右转','前方 200 m 左转','继续直行，即将到达','已到达目的地'];$('#turn').textContent=route||step===4?turns[step]:'准备出发';$('#route-detail').textContent=route?`前往${name}`:step===4?name:'选择目的地，开始旅程';$('#start-route').textContent=route?'结束导航':step===4?'重新导航 ↗':'开始导航 ↗';$('#next-step').hidden=!route;$('#destination').disabled=route;$('#wide-turn').textContent=$('#turn').textContent;$('#wide-time').textContent=$('#hud-time').textContent}
$('#destination').onchange=()=>{step=0;renderRoute()};$('#start-route').onclick=()=>{if(!connected){toast('请先在设备页连接演示设备');show('home');return}if(route){route=false;step=0;$('#route-status').textContent='导航已结束，可以选择新的目的地。'}else{route=true;step=0;$('#route-status').textContent='导航中 · 点击下方按钮模拟前进。'}renderRoute()};$('#next-step').onclick=()=>{step++;if(step>=4){step=4;route=false;$('#route-status').textContent='已到达，旅程完成。'}renderRoute();toast(voice?$('#turn').textContent:'路线已更新')};$('#expand-hud').onclick=()=>$('#landscape').showModal();$('#close-hud').onclick=()=>$('#landscape').close();
function stopSound(){nodes.forEach(n=>{try{n.stop()}catch{}});nodes=[];playing=false;$('#play').textContent='▶';$('#play').setAttribute('aria-label','播放氛围音');$('.album').classList.remove('playing')}
async function startSound(){try{ctx??=new(window.AudioContext||window.webkitAudioContext)();await ctx.resume();gain=ctx.createGain();gain.gain.value=Number($('#volume').value)/100*.12;gain.connect(ctx.destination);[1,1.5,2].forEach((ratio,i)=>{const o=ctx.createOscillator();o.type='sine';o.frequency.value=tracks[track][2]*ratio;o.detune.value=i*2;o.connect(gain);o.start();nodes.push(o)});playing=true;$('#play').textContent='Ⅱ';$('#play').setAttribute('aria-label','暂停氛围音');$('.album').classList.add('playing')}catch{toast('当前浏览器暂时无法播放音频')}}
$('#play').onclick=()=>playing?stopSound():startSound();function changeTrack(delta){const was=playing;stopSound();track=(track+delta+tracks.length)%tracks.length;elapsed=0;$('#track-name').textContent=tracks[track][0];$('#track-sub').textContent=tracks[track][1];$('.album-inner small').textContent=tracks[track][0].toUpperCase();updateTime();if(was)startSound()}$('#previous').onclick=()=>changeTrack(-1);$('#next').onclick=()=>changeTrack(1);function updateTime(){$('#elapsed').textContent=`${Math.floor(elapsed/60)}:${String(elapsed%60).padStart(2,'0')}`;$('#seek').value=elapsed}$('#seek').oninput=()=>{elapsed=Number($('#seek').value);updateTime()};setInterval(()=>{if(playing){elapsed++;if(elapsed>=180){elapsed=180;stopSound()}updateTime()}},1000);$('#volume').oninput=()=>{$('#volume-value').textContent=$('#volume').value+'%';if(gain)gain.gain.setTargetAtTime(Number($('#volume').value)/100*.12,ctx.currentTime,.1)};
$('#brightness').oninput=()=>{const value=Number($('#brightness').value);$('#brightness-value').textContent=value+'%';$('.brightness-preview').style.opacity=.3+value*.007;$('.hud-shade').style.opacity=1-value/100};$('#voice').onclick=()=>{voice=!voice;$('#voice').classList.toggle('on',voice);$('#voice').setAttribute('aria-checked',String(voice));toast(voice?'导航提示已开启':'导航提示已关闭')};document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('active',x===b));$('#mode-help').textContent=b.dataset.mode==='环境'?'保留环境感知 · 概念状态演示':'专注声音体验 · 概念状态演示';toast(`已切换${b.dataset.mode}模式`)});window.addEventListener('pagehide',stopSound);renderRoute();
